const out = [];
for (const item of $input.all()) {
  const body = (item.json.text || item.json.snippet || '');
  const get = (re) => { const m = body.match(re); return m ? m[1].trim() : null; };
  const zoneId = get(/Zone:\s*([^\n]+)/i) || 'Unknown';
  const toolId = get(/Tool:\s*([^\n]+)/i) || 'Unknown';
  const measured = parseFloat(get(/Measured Count:\s*([0-9.]+)/i) || '0');
  const limit = parseFloat(get(/ISO Class Limit:\s*([0-9.]+)/i) || '1');
  const particleSize = get(/Particle Size:\s*([^\n]+)/i) || '0.5um';
  const exceedanceRatio = limit > 0 ? Math.round((measured / limit) * 100) / 100 : 0;
  out.push({ json: { zone_id: zoneId, tool_id: toolId, measured_count: measured, iso_class_limit: limit,
    particle_size: particleSize, exceedance_ratio: exceedanceRatio, alert_timestamp: new Date().toISOString() } });
}
return out;

const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const capa = d.capa_result || {};
  const shutdown = Boolean(capa.requires_tool_shutdown || d.requires_tool_shutdown);
  out.push({ json: { ...d, tool_shutdown_required: shutdown, capa_id: capa.capa_id || null } });
}
return out;
